        display: inline-block;
    }
    .stat-facet-icon.__active {
        transform: rotate(180deg);
    }
    .search_bar ul.stat-targets-list {
        margin-bottom: 1.2rem;
    }
    .stat-piker.js-picker_model {
        padding: 0.8rem;
    }
    .stat-multiple_select {
        z-index: 1500;
        width: 100vw;
        height: 100vh;
        position: fixed;
        top: 0;
        left: 0;
        display: none;
    }
    .stat-multiple_select-layer {
        background-color: rgba(0, 0, 0, .4);
        justify-content: center;
        align-items: center;
        display: flex;
        width: 100%;
        height: 100%;
    }
    .stat-multiple_select-frame {
        min-width: 60vw;
        max-width: 80vw;
        border: 5px solid rgba(213, 227, 246, 1);
        background-color: #fff;
    }
    .stat-multiple_select-header {
        background-color: #4185d7;
        color: #fff;
        padding: 6px 10px;
        display: flex;
        align-items: center;
    }
    .stat-multiple_select-header-close {
        background-color: #fff;
        color: #333;
        border-radius: 3px;
        border: solid 1px #999;
        height: 24px;
        line-height: 24px;
        width: 24px;
        text-align: center;
        font-weight: bold;
        cursor: pointer;
        margin-left: auto;
    }
    .stat-multiple_select-title {
    }
    .stat-multiple_select-body {
        margin: 10px;
        max-height: 60vh;
        overflow-x: hidden;
        overflow-y: auto;
        border: 1px solid #ccc;
    }
    .stat-multiple_select-footer {
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .stat-multiple_select-close,
    .stat-multiple_select-done {
        padding: 2.2rem 3rem;
        margin: 1rem;
        border-radius: 5px;
        display: flex;
        justify-content: center;
        align-items: center;
        cursor: pointer;
        min-width: 100px;
    }
    .stat-multiple_select-close {
        font-size: 14px;
        line-height: 1;
        display: block;
        min-height: 30px;
        margin-bottom: 20px;
        padding: 9px 5px 7px;
        padding: 8px 5px 6px;
        transition-duration: .3s;
        transition-property: background-color color border-color;
        text-align: center;
        text-decoration: none;
        color: #084ba2;
        border: solid 1px #084ba2;
        border-radius: 5px;
        background-color: #fff;
    }
    .stat-multiple_select-done {
        font-size: 14px;
        line-height: 1;
        display: block;
        min-height: 30px;
        margin-bottom: 20px;
        padding: 9px 5px 7px;
        transition-duration: .3s;
        transition-property: background-color color border-color;
        text-align: center;
        text-decoration: none;
        color: #fff;
        border-radius: 5px;
        background-color: #084ba2;
    }
    .stat-multiple_select-done:hover,
    .stat-multiple_select-done:focus {
        background-color: #4185d7;
    }
    .stat-multiple_select-close:hover,
    .stat-multiple_select-close:focus {
        /*background-color: #fff;*/
        text-decoration: none;
        color: #fff;
        border: solid 1px #4185d7;
        background-color: #286bc6;
    }
    .stat-multiple_select-item {
        display: flex;
        align-items: center;
        justify-content: flex-start;
        border-bottom: 1px dashed #ddd;
        padding: 0.6rem;
    }
    .stat-multiple_select-item-label {
        color: #286bc6;
        font-weight: normal;
        display: flex;
        align-items: flex-start;
        justify-content: flex-start;
        cursor: default;
    }
    input.stat-multiple_select-item-check {
        flex: none;
        margin: 0;
        padding: 0;
    }
    .stat-multiple_select-item-title {
        display: inline-block;
        margin: 0 10px;
        white-space: normal;
    }
    .stat-cursor-pointer {
        cursor: pointer;
        cursor: hand;
    }

